# يبني سيناريوهات جلسات التقييم القصيرة للشركات (3 أيام عمل مكثفة، نحو ساعتين لكل دور):
#   pm-assessment     مدير منتجات: من أحداث السيناريو الكامل
#   sales-assessment  أخصائي مبيعات: محتوى خاص + أحداث مشتركة
#   cs-assessment     نجاح العملاء وخدمتهم: محتوى خاص + أحداث مشتركة
# الاستخدام: python3 scripts/build-assessment.py
import json, copy
src = json.load(open('data/scenarios/pm-first-30-days.json'))
ev = {e['id']: e for e in src['events'] + src['randomEvents']}

def take(eid, day):
    e = copy.deepcopy(ev[eid]); e['day'] = day; e['dueInDays'] = 1
    for k in ('delegable', 'minDay', 'weight', 'condition'): e.pop(k, None)
    return e

def brief(role_text, frm):
    return {"id": "a_brief", "day": 1, "type": "message", "from": frm, "priority": "normal", "dueInDays": 1, "skills": ["communication"],
        "title": "FYA: موجز سريع قبل أن تبدأ",
        "body": f"أهلًا بك. أمامك ثلاثة أيام عمل مكثفة {role_text} في NOVA TECH. PFA دليل الشركة: المنتج، والعملاء، والمؤشرات. اقرأه أولًا (5 دقائق)، ثم ابدأ ببريدك. تستطيع سؤال أي زميل من صفحة «فريقي».",
        "attachments": ["handbook", "glossary"],
        "options": [{"id": "read", "label": "قرأت الموجز", "quality": 0.85, "effects": [{"op": "trust", "who": frm, "value": 2}]}]}

def opt(i, label, q, effects=(), result=None, tone=None):
    o = {"id": i, "label": label, "quality": q, "effects": list(effects)}
    if result: o["result"] = result
    if tone: o["tone"] = tone
    return o

def concern(i, owner, label, criteria, keywords, ok, open_, min_hits=2, on=()):
    c = {"id": i, "owner": owner, "label": label, "criteria": criteria, "keywords": keywords, "minHits": min_hits, "replyAddressed": ok, "replyOpen": open_}
    if on: c["onAddressed"] = list(on)
    return c

def talk(i, day, frm, chair, title, body, topic, opening, concerns, options, outcomes, rules, *, kind="message", mode="chat", participants=None,
         priority="high", skills=("communication", "decisions"), stance=None, expire=None, placeholder="اكتب ردك.", rounds=2):
    e = {"id": i, "day": day, "type": kind, "from": frm, "priority": priority, "dueInDays": 1, "skills": list(skills), "title": title, "body": body, "options": options,
         "dialogue": {"mode": mode, "chair": chair, "participants": participants or [chair], "maxRounds": rounds, "topic": topic, "placeholder": placeholder,
                      "opening": [{"speaker": s, "text": t} for s, t in opening], "concerns": concerns,
                      "outcomes": {k: {"guide": g, "closing": cl} for k, (g, cl) in outcomes.items()},
                      "stanceKeywords": stance or {}, "closeRules": [({"outcome": o, "minAddressed": n} if n else {"outcome": o}) for o, n in rules]}}
    if expire: e["onExpire"] = {"result": expire[0], "effects": list(expire[1])}
    return e

def doc(i, day, frm, title, body, sections, good, weak, *, min_words=80, priority="high", skills=("output", "analysis")):
    return {"id": i, "day": day, "type": "task", "category": "task", "from": frm, "priority": priority, "dueInDays": 1, "skills": list(skills), "title": title, "body": body,
            "deliverable": {"minWords": min_words, "passScore": 0.6, "sections": [{"id": s, "label": l, "keywords": k} for s, l, k in sections],
                            "onGood": {"result": good[0], "effects": list(good[1])}, "onWeak": {"result": weak[0], "effects": list(weak[1])}},
            "onExpire": {"result": f"لم يُسلَّم: {title}.", "effects": [{"op": "trust", "who": frm, "value": -6}]}}

T = lambda who, v: {"op": "trust", "who": who, "value": v}
ADD = lambda path, v: {"op": "add", "path": path, "value": v}

def scenario(sid, role, role_id, manager, team, events):
    out = {"id": sid, "derivedFrom": src['id'], "company": src['company'], "role": role, "manager": manager, "team": team,
           "lengthDays": 3, "randomEventChance": 0, "initialTrust": src['initialTrust'], "events": sorted(events, key=lambda e: e['day']), "randomEvents": [], "insights": [], "memos": []}
    if role_id: out["roleId"] = role_id
    json.dump(out, open(f'data/scenarios/{sid}.json', 'w'), ensure_ascii=False, indent=1)
    print(sid, len(events), 'events')

# ——— مدير المنتجات ———
scenario('pm-assessment', 'Product Manager — جلسة تقييم', src['roleId'], src['manager'], ["ux", "eng_lead", "dev2", "analyst"],
    [brief('مديرًا للمنتجات', 'cpo')] + [take(i, d) for i, d in [
        ('d1_ufuq_complaint', 1), ('d1_usage_report', 1), ('d1_sales_request', 1),
        ('d3_sprint_priority', 2), ('d7_delegation', 2), ('d6_competitor_price', 2),
        ('d5_mgmt_meeting', 3), ('d23_feedback_1on1', 3), ('d25_outage', 3)]])

